+RBTreeOrdering ZMemoryWorker::ZHeatingRequestTreeComparator::cmp(zoffset first, zoffset second) {
+  if (first < second) {
+    // Start before second
+    return RBTreeOrdering::LT;
+  }
+
+  if (first > second) {
+    // Start after second
+    return RBTreeOrdering::GT;
+  }
+
+  // Same position
+  return RBTreeOrdering::EQ;
+}
